#include "Monstey_FearDbPacked.hpp"
#include "Monstey_Json.hpp"
#include <algorithm>
#include <array>
#include <fstream>
#include <iostream>
#include <random>
#include <vector>
using namespace Monstey;
namespace {
using Monstey_U32=std::uint32_t;
std::uint64_t Monstey_Groups=0,Monstey_Cases=0,Monstey_Checks=0;
void Monstey_Check(bool v,const char* text){++Monstey_Checks;if(!v)throw std::runtime_error(text);}
void Monstey_Add(std::vector<std::uint8_t>& v,Monstey_U32 word){for(unsigned i=0;i<4;++i)v.push_back(static_cast<std::uint8_t>(word>>(i*8)));}
Monstey_U32 Monstey_Get(const Monstey_FearDbPackedImage& image,Monstey_U32 at,unsigned width=4){Monstey_U32 word=0;for(unsigned i=0;i<width;++i)word|=Monstey_U32(image.allocation.at(at-image.base+i))<<(i*8);return word;}
struct Monstey_Attribute {Monstey_U32 name=0,type=3,usage=0;std::vector<Monstey_U32> values;};
struct Monstey_Record {Monstey_U32 name=0;std::vector<Monstey_Attribute> attributes;};
struct Monstey_Category {Monstey_U32 name=0;std::vector<Monstey_Record> records;};
struct Monstey_Fixture {
 std::vector<std::uint8_t> pool{0,'Z',0,'A',0};std::vector<Monstey_Category> categories;std::array<Monstey_U32,4> extra{};
 std::array<Monstey_U32,4> Counts()const {std::array<Monstey_U32,4> n{static_cast<Monstey_U32>(categories.size()),0,0,0};for(const auto&c:categories){n[1]+=static_cast<Monstey_U32>(c.records.size());for(const auto&r:c.records){n[2]+=static_cast<Monstey_U32>(r.attributes.size());for(const auto&a:r.attributes)n[3]+=static_cast<Monstey_U32>(a.values.size());}}return n;}
 std::vector<std::uint8_t> Serialize() const {std::vector<std::uint8_t> v;Monstey_Add(v,0x42444147);Monstey_Add(v,3);Monstey_Add(v,static_cast<Monstey_U32>(pool.size()));const auto n=Counts();for(unsigned i=0;i<4;++i)Monstey_Add(v,n[i]+extra[i]);v.insert(v.end(),pool.begin(),pool.end());Monstey_Add(v,static_cast<Monstey_U32>(categories.size()));for(const auto&c:categories){Monstey_Add(v,c.name);Monstey_Add(v,static_cast<Monstey_U32>(c.records.size()));for(const auto&r:c.records){Monstey_Add(v,r.name);Monstey_Add(v,static_cast<Monstey_U32>(r.attributes.size()));for(const auto&a:r.attributes){Monstey_Add(v,a.name);Monstey_Add(v,a.type);Monstey_Add(v,a.usage);Monstey_Add(v,static_cast<Monstey_U32>(a.values.size()));for(auto x:a.values)Monstey_Add(v,x);}}}return v;}
 std::vector<std::size_t> ReadSizes()const {std::vector<std::size_t> sizes{28,pool.size(),4};for(const auto&c:categories){sizes.push_back(8);for(const auto&r:c.records){sizes.push_back(8);for(const auto&a:r.attributes){sizes.push_back(16);for(std::size_t i=0;i<a.values.size();++i)sizes.push_back(4);}}}return sizes;}
};
const std::array<std::uint8_t,5> Monstey_Name{'d','b',0,0xff,0xff};
struct Monstey_Layout {std::vector<Monstey_U32> category;std::vector<std::vector<Monstey_U32>> record;std::vector<std::vector<std::vector<Monstey_U32>>> attribute,values;Monstey_U32 end=0;};
Monstey_Layout Monstey_Compute(const Monstey_Fixture& f,Monstey_U32 base){Monstey_Layout l;const auto db=base+static_cast<Monstey_U32>(f.pool.size());Monstey_U32 next=db+23u;for(std::size_t c=0;c<f.categories.size();++c)l.category.push_back(next+static_cast<Monstey_U32>(c)*16u);next+=static_cast<Monstey_U32>(f.categories.size())*16u;
 l.record.resize(f.categories.size());l.attribute.resize(f.categories.size());l.values.resize(f.categories.size());
 for(std::size_t c=0;c<f.categories.size();++c){const auto&cat=f.categories[c];for(std::size_t r=0;r<cat.records.size();++r)l.record[c].push_back(next+static_cast<Monstey_U32>(r)*16u);next+=static_cast<Monstey_U32>(cat.records.size())*16u;l.attribute[c].resize(cat.records.size());l.values[c].resize(cat.records.size());for(std::size_t r=0;r<cat.records.size();++r){const auto&rec=cat.records[r];for(std::size_t a=0;a<rec.attributes.size();++a)l.attribute[c][r].push_back(next+static_cast<Monstey_U32>(a)*16u);next+=static_cast<Monstey_U32>(rec.attributes.size())*16u;for(const auto&a:rec.attributes){l.values[c][r].push_back(next);next+=static_cast<Monstey_U32>(a.values.size())*4u;}}}l.end=next;return l;}
void Monstey_Verify(const Monstey_Fixture&f,const Monstey_FearDbPackedImage& image){const auto l=Monstey_Compute(f,image.base);const auto db=image.base+static_cast<Monstey_U32>(f.pool.size());Monstey_Check(image.database==db,"database follows raw pool");Monstey_Check(Monstey_Get(image,db)==image.base,"single allocation base ownership");Monstey_Check(Monstey_Get(image,db+4)==db+20,"copied database name position");Monstey_Check(Monstey_Get(image,db+8)==f.categories.size(),"root count is stream count");Monstey_Check(Monstey_Get(image,db+12)==db+23,"category array after terminated name");Monstey_Check(Monstey_Get(image,db+16)==0,"loader initializes refcount zero");Monstey_Check(image.used_bytes==l.end-image.base,"allocation cursor final position");Monstey_Check(image.allocation.at(db+20-image.base)=='d'&&image.allocation.at(db+21-image.base)=='b'&&image.allocation.at(db+22-image.base)==0,"name terminated exact, extra ignored");Monstey_Check(std::equal(f.pool.begin(),f.pool.end(),image.allocation.begin()),"raw pool unchanged");
 Monstey_U32 cursor=db+23u+static_cast<Monstey_U32>(f.categories.size())*16u;
 for(std::size_t c=0;c<f.categories.size();++c){const auto&cat=f.categories[c];const auto ch=l.category[c];Monstey_Check(Monstey_Get(image,ch)==image.base+cat.name,"category name pointer not validated");Monstey_Check(Monstey_Get(image,ch+4)==db&&Monstey_Get(image,ch+8)==cat.records.size()&&Monstey_Get(image,ch+12)==cursor,"category metadata");cursor+=static_cast<Monstey_U32>(cat.records.size())*16u;
  for(std::size_t r=0;r<cat.records.size();++r){const auto&rec=cat.records[r];const auto rh=l.record[c][r];Monstey_Check(Monstey_Get(image,rh)==image.base+rec.name&&Monstey_Get(image,rh+4)==ch&&Monstey_Get(image,rh+8)==rec.attributes.size()&&Monstey_Get(image,rh+12)==cursor,"record metadata");cursor+=static_cast<Monstey_U32>(rec.attributes.size())*16u;
   for(std::size_t a=0;a<rec.attributes.size();++a){const auto&att=rec.attributes[a];const auto ah=l.attribute[c][r][a],vh=l.values[c][r][a];Monstey_Check(vh==cursor,"value array reservation");Monstey_Check(Monstey_Get(image,ah)==image.base+att.name&&Monstey_Get(image,ah+4)==rh,"attribute parent/name");Monstey_Check(Monstey_Get(image,ah+8,2)==(att.values.size()&65535u)&&Monstey_Get(image,ah+10,1)==(att.type&255u)&&Monstey_Get(image,ah+11,1)==(att.usage&255u),"physical count narrows only in stored metadata");Monstey_Check(Monstey_Get(image,ah+12)==vh,"value pointer");
    for(std::size_t i=0;i<att.values.size();++i){auto expected=att.values[i];if(att.type-4u<=4u)expected+=image.base;if((att.type&255u)==9u&&i<(att.values.size()&65535u)){const auto target_cat=expected>>16;const auto target_rec=expected&65535u;expected=target_cat<l.record.size()&&target_rec<l.record[target_cat].size()?l.record[target_cat][target_rec]:0;}Monstey_Check(Monstey_Get(image,vh+static_cast<Monstey_U32>(i)*4u)==expected,"value relocation/reference resolution/raw association");}cursor+=static_cast<Monstey_U32>(att.values.size())*4u;
   }
  }
 }
 Monstey_Check(cursor==l.end,"independent cursor agreement");for(std::size_t i=image.used_bytes;i<image.allocation.size();++i)Monstey_Check(image.allocation[i]==0,"owned unwritten tail placeholder");
}
Monstey_FearDbPackedImage Monstey_Load(const Monstey_Fixture&f,Monstey_U32 base=0x10203040){auto serialized=f.Serialize();Monstey_FearDbPackedInput input{serialized};auto result=Monstey_FearDbLoadPacked(input,Monstey_Name,base);Monstey_Check(result.status==Monstey_FearDbPackedStatus::loaded&&result.image.has_value(),"valid packed fixture load");Monstey_Check(input.position==serialized.size()&&input.read_calls==f.ReadSizes().size(),"exact read count and byte consumption");Monstey_Verify(f,*result.image);++Monstey_Cases;return std::move(*result.image);}
void Monstey_Empty(){for(unsigned pool=0;pool<8;++pool){Monstey_Fixture f;f.pool.resize(pool);auto image=Monstey_Load(f);Monstey_Check(image.allocation.size()==pool+23u,"empty allocation size");}++Monstey_Groups;}
void Monstey_Types(){for(Monstey_U32 type=0;type<512;++type){Monstey_Fixture f;f.categories={Monstey_Category{0xffffffffu,{Monstey_Record{0x80000000u,{Monstey_Attribute{0xfffffffeu,type,0x12340000u+type,{0,1,0xffffffffu,0x80000000u}}}}}}};(void)Monstey_Load(f);}for(Monstey_U32 type:std::array<Monstey_U32,5>{0x80000004u,0xffffff04u,0x10004u,0x109u,0x80000009u}){Monstey_Fixture f;f.categories={Monstey_Category{0,{Monstey_Record{0,{Monstey_Attribute{0,type,0xffffffffu,{0,0x10000,0xffffffffu}}}}}}};(void)Monstey_Load(f);}++Monstey_Groups;}
void Monstey_CountNarrow() {
 for(auto count:std::array<Monstey_U32,5>{0,1,65535,65536,65537})
  for(auto type:std::array<Monstey_U32,3>{3,9,0x109}) {
   Monstey_Fixture f;
   Monstey_Attribute a{0,type,0xabcdef78,{}};
   a.values.resize(count);
   for(Monstey_U32 i=0;i<count;++i)a.values[i]=i%3u==0?0u:i%3u==1?0x00010000u:0xffffffffu;
   Monstey_Record first{0,{std::move(a)}};
   f.categories.push_back(Monstey_Category{0,{std::move(first)}});
   f.categories.push_back(Monstey_Category{0,{Monstey_Record{0,{}}}});
   (void)Monstey_Load(f);
  }
 ++Monstey_Groups;
}
void Monstey_Random(){std::mt19937 rng(0x47414442);for(unsigned n=0;n<512;++n){Monstey_Fixture f;f.pool.resize(rng()%32);f.categories.resize(rng()%5);for(auto&c:f.categories){c.name=rng();c.records.resize(rng()%5);for(auto&r:c.records){r.name=rng();r.attributes.resize(rng()%6);for(auto&a:r.attributes){a.name=rng();a.type=rng()%12;a.usage=rng();a.values.resize(rng()%9);for(auto&v:a.values)v=a.type==9?rng()%0x50005:rng();}}}if(n%7==0)f.extra={1,2,3,4};(void)Monstey_Load(f,0x01000000u+n*0x10000u);}++Monstey_Groups;}
void Monstey_ShortReads(){Monstey_Fixture f;f.categories={Monstey_Category{1,{Monstey_Record{3,{Monstey_Attribute{0,4,7,{0,1,2}},Monstey_Attribute{0,9,8,{0,0xffffffffu}}}}}}};const auto full=f.Serialize();const auto sizes=f.ReadSizes();for(std::size_t cut=0;cut<full.size();++cut){Monstey_FearDbPackedInput input{std::span(full).first(cut)};const auto result=Monstey_FearDbLoadPacked(input,Monstey_Name,0x10000000);std::size_t pos=0,failed=0;while(failed<sizes.size()&&sizes[failed]<=cut-pos){pos+=sizes[failed];++failed;}const auto expected=failed==0?Monstey_FearDbPackedStatus::header_read_failed:failed==1?Monstey_FearDbPackedStatus::pool_read_failed:Monstey_FearDbPackedStatus::graph_read_failed;Monstey_Check(result.status==expected&&!result.image,"short read returns no resource");Monstey_Check(input.position==pos&&input.read_calls==failed+1,"failed read leaves owned cursor unchanged and stops");const auto counts=f.Counts();const auto expected_bytes=static_cast<Monstey_U32>(f.pool.size())+23u+16u*(counts[0]+counts[1]+counts[2])+4u*counts[3];Monstey_Check(result.allocation_bytes==(failed==0?0u:expected_bytes),"allocation only after header");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_Trailing(){Monstey_Fixture f;f.categories={Monstey_Category{3,{}},Monstey_Category{1,{}}};auto bytes=f.Serialize();const auto end=bytes.size();bytes.insert(bytes.end(),{0xaa,0xbb,0xcc});Monstey_FearDbPackedInput input{bytes};const auto result=Monstey_FearDbLoadPacked(input,Monstey_Name,0x10000000);Monstey_Check(result.image.has_value()&&input.position==end,"loader must not consume/reject trailing bytes");Monstey_Verify(f,*result.image);++Monstey_Cases;++Monstey_Groups;}
void Monstey_Header(){Monstey_Fixture f;for(unsigned word=0;word<2;++word){auto bytes=f.Serialize();bytes[word*4]^=0xff;Monstey_FearDbPackedInput input{bytes};const auto result=Monstey_FearDbLoadPacked(input,{},0);Monstey_Check(result.status==Monstey_FearDbPackedStatus::invalid_header&&!result.image&&input.position==28&&input.read_calls==1,"invalid header skips name/allocation/pool");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_OwnedFaults(){Monstey_Fixture f;f.categories={Monstey_Category{0,{Monstey_Record{0,{Monstey_Attribute{0,3,0,{42}}}}}}};auto bytes=f.Serialize();for(unsigned i=12;i<28;++i)bytes[i]=0;Monstey_FearDbPackedInput input{bytes};bool caught=false;try{(void)Monstey_FearDbLoadPacked(input,Monstey_Name,0x10000000);}catch(const Monstey_FearDbFault&e){caught=e.writing;}Monstey_Check(caught,"insufficient header allocation rejects only consumed owned store");++Monstey_Cases;auto valid=f.Serialize();Monstey_FearDbPackedInput in{valid};bool named=false;try{(void)Monstey_FearDbLoadPacked(in,std::array<std::uint8_t,1>{'x'},0x10000000);}catch(const std::invalid_argument&){named=true;}Monstey_Check(named&&in.position==28&&in.read_calls==1,"unterminated owned name boundary after header");++Monstey_Cases;++Monstey_Groups;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW report required");Monstey_Empty();Monstey_Types();Monstey_CountNarrow();Monstey_Random();Monstey_ShortReads();Monstey_Trailing();Monstey_Header();Monstey_OwnedFaults();std::ofstream(argv[1],std::ios::binary)<<Monstey_Json::object({{"schema","Monstey.FearPackedTests/1"},{"passed",true},{"groups",Monstey_Groups},{"cases",Monstey_Cases},{"checks",Monstey_Checks},{"original_program_executed",false}}).dump(2)<<'\n';std::cout<<"PASS "<<Monstey_Groups<<" groups "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
